shed #bdcede;border-radius:16px;padding:55px 20px;color:#60768b}.empty strong{display:block;font-size:18px;color:var(--navy);margin-bottom:8px}.pagination{margin-top:30px}.footer{border-top:1px solid var(--border);background:#fff;padding:22px 0;color:#657a8e;font-size:12px;text-align:center}a:focus-visible,button:focus-visible{outline:3px solid #3e9fe5;outline-offset:3px}
