<main class="container main">
<form class="filter" action="{{ route('projects.index') }}" method="GET" role="search"><div class="field"><label for="project-search">البحث عن مشروع</label><input id="project-search" name="q" value="{{ request('q') }}" placeholder="اكتب اسم المشروع" maxlength="100"></div><div class="field"><label for="project-category">تصنيف المشروع</label><select id="project-category" name="category"><option value="">جميع التصنيفات</option>@foreach($categories as $category)<option value="{{ $category }}" @selected(request('category')===$category)>{{ (new \App\Models\CharitableProject(['category'=>$category]))->category_label }}</option>@endforeach</select></div><button class="btn btn-primary" type="submit">بحث عن المشاريع</button><a class="btn btn-outline" href="{{ route('projects.index') }}">إعادة ضبط</a></form>
<div class="section-heading"><div><h2>المشاريع المتاحة للمساهمة</h2><p>يتم عرض المشاريع النشطة وغير مكتملة التمويل فقط.</p></div><span style="color:#64748b;font-size:13px">{{ $projects->total() }} مشروع</span></div>
<div class="grid">
@forelse($projects as $project)
@php($target = max(0,(float)$project->target_budget))
@php($collected = max(0,(float)$project->collected_amount))
@php($remaining = max(0,$target-$collected))
@php($percentage = $target > 0 ? max(0,min(100,($collected/$target)*100)) : 0)
<article class="card"><div class="card-top"><span class="category">{{ $project->category_label }}</span><span class="state">نشط • يحتاج تمويلًا</span></div><div class="card-body"><h3><a href="{{ route('projects.show',$project) }}" style="color:inherit;text-decoration:none">{{ $project->title }}</a></h3><p class="description">{{ \Illuminate\Support\Str::limit($project->description ?: 'مشروع خيري يهدف إلى دعم المجتمع والمستفيدين.',130) }}</p>
<div class="funding"><div class="item"><span>المبلغ المستهدف</span><strong><span class="sz-money"><span class="sz-money-currency">د.ل</span><span class="sz-money-number">{{ number_format($target,2) }}</span></span></strong></div><div class="item"><span>المبلغ المحصل</span><strong><span class="sz-money"><span class="sz-money-currency">د.ل</span><span class="sz-money-number">{{ number_format($collected,2) }}</span></span></strong></div><div class="item"><span>المبلغ المتبقي</span><strong><span class="sz-money"><span class="sz-money-currency">د.ل</span><span class="sz-money-number">{{ number_format($remaining,2) }}</span></span></strong></div></div>
<div class="progress-label"><span>نسبة التمويل</span><span>{{ number_format($percentage,1) }}%</span></div><div class="track" role="progressbar" aria-label="نسبة تمويل المشروع" aria-valuemin="0" aria-valuemax="100" aria-valuenow="{{ round($percentage,1) }}"><div class="fill" style="width:{{ $percentage }}%"></div></div>
<div class="card-actions"><a class="btn btn-outline" href="{{ route('projects.show',$project) }}">عرض التفاصيل</a>@if($project->status === 'ACTIVE' && $project->target_budget > $project->collected_amount && (!auth()->check() || !auth()->user()->hasRole('admin')))<a class="btn btn-primary" href="{{ route('donations.bank.create',['type'=>'project','id'=>$project->id]) }}">تبرع الآن</a>@else <a class="btn btn-primary" href="{{ route('admin.projects.edit',$project) }}">إدارة المشروع</a>@endif</div>
</div></article>
@empty<div class="empty"><strong>لا توجد مشاريع مطابقة حاليًا</strong><p>يمكنك تغيير كلمات البحث أو اختيار تصنيف آخر للاطلاع على المشاريع المتاحة.</p><a class="btn btn-primary" href="{{ route('projects.index') }}">عرض جميع المشاريع</a></div>@endforelse
</div><div class="pagination">{{ $projects->links() }}</div>
